// O último estado mora no próprio fluxo. Só vale com ele publicado: rodando na mão pelo
// editor, o n8n não guarda nada, e todo teste parece a primeira vez.
const memória = $getWorkflowStaticData('global');
const resposta = $input.first().json;

// Rodando pelo botão do editor eu mando assim mesmo, marcado como teste: é o jeito de
// conferir que o webhook do Discord responde sem ter que derrubar o Lavalink de verdade.
// Só o que o n8n chamar de teste conta como teste — na dúvida, trato como de verdade.
const modo = typeof $execution === 'object' && $execution ? $execution.mode : undefined;
const teste = modo === 'test' || modo === 'manual';

let estado;
let detalhe;

if (resposta.statusCode === undefined) {
  // nem respondeu: o contêiner do bot está fora, ou a API não subiu
  estado = 'sem resposta';
  detalhe = resposta.error?.message ?? 'A API não respondeu.';
} else {
  const saúde = resposta.body && typeof resposta.body === 'object' ? resposta.body : {};
  estado = saúde.status ?? `HTTP ${resposta.statusCode}`;
  detalhe = `Discord: ${saúde.discord ?? '?'} · Lavalink: ${saúde.lavalink ?? '?'}`;
}

const antes = memória.estado;

// teste não mexe na memória: senão um clique no editor comeria o aviso da próxima mudança
if (!teste) {
  memória.estado = estado;
}

// na primeira rodada só anoto, a não ser que já comece mal
if (!teste && (antes === undefined ? estado === 'ok' : antes === estado)) {
  return [];
}

const títulos = {
  ok: '🟢 O AlephBot voltou',
  degraded: '🟡 O AlephBot está sem música: o Lavalink caiu',
  down: '🔴 O AlephBot caiu do Discord',
  'sem resposta': '🔴 O AlephBot não responde',
};

const título = teste
  ? `🔎 Teste: o AlephBot está "${estado}"`
  : (títulos[estado] ?? `⚠️ AlephBot: ${estado}`);

const rodapé = teste
  ? '\n-# teste manual pelo editor — ninguém caiu'
  : (antes === undefined ? '' : `\n-# antes: ${antes}`);

return [{ json: { content: `**${título}**\n${detalhe}${rodapé}` } }];
